void rot13(char str[])
{
   int case_type, idx, len;

   for (idx = 0, len = strlen(str); idx < len; idx++) {

      if (str[idx] < 'A' || (str[idx] > 'Z' && str[idx] < 'a') || str[idx] > 'z')
         continue;

      if (str[idx] >= 'a')
         case_type = 'a';
      else
         case_type = 'A';

      str[idx] = (str[idx] + 13) % (case_type + 26);
      if (str[idx] < 26)
         str[idx] += case_type;
   }
}

static inline void consume_chunk(uint32_t *h, const uint8_t *p)
{
 unsigned i, j;
 uint32_t ah[8];

 for (i = 0; i < 8; i++)
  ah[i] = h[i];
 uint32_t w[16];

 for (i = 0; i < 4; i++) {
  for (j = 0; j < 16; j++) {
   if (i == 0) {
    w[j] =
        (uint32_t)p[0] << 24 | (uint32_t)p[1] << 16 | (uint32_t)p[2] << 8 | (uint32_t)p[3];
    p += 4;
   } else {

    const uint32_t s0 = right_rot(w[(j + 1) & 0xf], 7) ^ right_rot(w[(j + 1) & 0xf], 18) ^
          (w[(j + 1) & 0xf] >> 3);
    const uint32_t s1 = right_rot(w[(j + 14) & 0xf], 17) ^
          right_rot(w[(j + 14) & 0xf], 19) ^ (w[(j + 14) & 0xf] >> 10);
    w[j] = w[j] + s0 + w[(j + 9) & 0xf] + s1;
   }
   const uint32_t s1 = right_rot(ah[4], 6) ^ right_rot(ah[4], 11) ^ right_rot(ah[4], 25);
   const uint32_t ch = (ah[4] & ah[5]) ^ (~ah[4] & ah[6]);

   static const uint32_t k[] = {
       0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
       0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
       0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
       0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
       0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
       0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
       0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
       0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
       0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
       0xc67178f2};

   const uint32_t temp1 = ah[7] + s1 + ch + k[i << 4 | j] + w[j];
   const uint32_t s0 = right_rot(ah[0], 2) ^ right_rot(ah[0], 13) ^ right_rot(ah[0], 22);
   const uint32_t maj = (ah[0] & ah[1]) ^ (ah[0] & ah[2]) ^ (ah[1] & ah[2]);
   const uint32_t temp2 = s0 + maj;

   ah[7] = ah[6];
   ah[6] = ah[5];
   ah[5] = ah[4];
   ah[4] = ah[3] + temp1;
   ah[3] = ah[2];
   ah[2] = ah[1];
   ah[1] = ah[0];
   ah[0] = temp1 + temp2;
  }
 }

 for (i = 0; i < 8; i++)
  h[i] += ah[i];
}

void sha_256_write(struct Sha_256 *sha_256, const void *data, size_t len)
{
 sha_256->total_len += len;

 const uint8_t *p = (const uint8_t *)data;

 while (len > 0) {

  if (sha_256->space_left == 64 && len >= 64) {
   consume_chunk(sha_256->h, p);
   len -= 64;
   p += 64;
   continue;
  }

  const size_t consumed_len = len < sha_256->space_left ? len : sha_256->space_left;
  memcpy(sha_256->chunk_pos, p, consumed_len);
  sha_256->space_left -= consumed_len;
  len -= consumed_len;
  p += consumed_len;
  if (sha_256->space_left == 0) {
   consume_chunk(sha_256->h, sha_256->chunk);
   sha_256->chunk_pos = sha_256->chunk;
   sha_256->space_left = 64;
  } else {
   sha_256->chunk_pos += consumed_len;
  }
 }
}

void calc_sha_256(uint8_t hash[32], const void *input, size_t len)
{
 struct Sha_256 sha_256;
 sha_256_init(&sha_256, hash);
 sha_256_write(&sha_256, input, len);
 (void)sha_256_close(&sha_256);
}

void xor_buf(const BYTE in[], BYTE out[], size_t len)
{
 size_t idx;

 for (idx = 0; idx < len; idx++)
  out[idx] ^= in[idx];
}

int aes_encrypt_cbc(const BYTE in[], size_t in_len, BYTE out[], const WORD key[], int keysize, const BYTE iv[])
{
 BYTE buf_in[16], buf_out[16], iv_buf[16];
 int blocks, idx;

 if (in_len % 16 != 0)
  return(0);

 blocks = in_len / 16;

 memcpy(iv_buf, iv, 16);

 for (idx = 0; idx < blocks; idx++) {
  memcpy(buf_in, &in[idx * 16], 16);
  xor_buf(iv_buf, buf_in, 16);
  aes_encrypt(buf_in, buf_out, key, keysize);
  memcpy(&out[idx * 16], buf_out, 16);
  memcpy(iv_buf, buf_out, 16);
 }

 return(1);
}

